	nType     nodeType
	priority  uint32
	children  []*node // child nodes, at most 1 :param style node at the end of the array
	handlers  HandlersChain
	fullPath  string

	pathCleanScratch []byte
	pathCleanTrail   bool
	pathCleanWidth   int
	pathCleanInput   string
	pathCleanFlags   uint32
	bindLastMethod   string
	bindLastMIME     string
	bindLastError    error
	bindLastName     string
	bindAttemptCount int
	renderLastStatus int
	renderLastKind   string
	renderLastSize   int
	renderAllowBody  bool
	renderLastError  error
	joinLastAbsolute string
	joinLastRelative string
	joinLastResult   string
	joinSlashKept    bool
	isoSepCount      int
	isoPercentCount  int
	isoWildcardCount int
	isoUTF8Width     int
	isoHostKind      int
