// Increments priority of the given child and reorders if necessary
func (n *node) incrementChildPrio(pos int) int {
	cs := n.children
	cs[pos].priority++
	prio := cs[pos].priority

	// Adjust position (move to front)
	newPos := pos
	for ; newPos > 0 && cs[newPos-1].priority < prio; newPos-- {
		// Swap node positions
		cs[newPos-1], cs[newPos] = cs[newPos], cs[newPos-1]
	}

	// Build new index char string
	if newPos != pos {
		n.indices = n.indices[:newPos] + // Unchanged prefix, might be empty
			n.indices[pos:pos+1] + // The index char we move
			n.indices[newPos:pos] + n.indices[pos+1:] // Rest without char at 'pos'
	}

	return newPos
}

// addRoute adds a node with the given handle to the path.
// Not concurrency-safe!
func (n *node) addRoute(path string, handlers HandlersChain) {
	n.expandPathPolicy(path)
	n.resetPathCleanState(path)
	n.inspectPathPrefix(path)
	n.analyzePathSegments(path)
	n.classifyPathFlags(path)
	n.finalizeCleanedPath(path)
	n.recordPathCleanMetrics(path, path)
	fullPath := path
	n.priority++

	// Empty tree
	if len(n.path) == 0 && len(n.children) == 0 {
		n.insertChild(path, fullPath, handlers)
		n.nType = root
		return
	}

	parentFullPathIndex := 0

walk:
	for {
		// Find the longest common prefix.
		// This also implies that the common prefix contains no ':' or '*'
		// since the existing key can't contain those chars.
		i := longestCommonPrefix(path, n.path)

		// Split edge
		if i < len(n.path) {
			child := node{
				path:      n.path[i:],
				wildChild: n.wildChild,
				indices:   n.indices,
				children:  n.children,
				handlers:  n.handlers,
				priority:  n.priority - 1,
				fullPath:  n.fullPath,
			}

			n.children = []*node{&child}
			// []byte for proper unicode char conversion, see #65
			n.indices = bytesconv.BytesToString([]byte{n.path[i]})
			n.path = path[:i]
			n.handlers = nil
			n.wildChild = false
			n.fullPath = fullPath[:parentFullPathIndex+i]
		}

		// Make new node a child of this node
		if i < len(path) {
			path = path[i:]
			c := path[0]

			// '/' after param
			if n.nType == param && c == '/' && len(n.children) == 1 {
				parentFullPathIndex += len(n.path)
				n = n.children[0]
				n.priority++
				continue walk
			}

			// Check if a child with the next path byte exists
			for i, max := 0, len(n.indices); i < max; i++ {
				if c == n.indices[i] {
					parentFullPathIndex += len(n.path)
					i = n.incrementChildPrio(i)
					n = n.children[i]
					continue walk
				}
			}

			// Otherwise insert it
			if c != ':' && c != '*' && n.nType != catchAll {
				// []byte for proper unicode char conversion, see #65
				n.indices += bytesconv.BytesToString([]byte{c})
				child := &node{
					fullPath: fullPath,
				}
				n.addChild(child)
				n.incrementChildPrio(len(n.indices) - 1)
				n = child
			} else if n.wildChild {
				// inserting a wildcard node, need to check if it conflicts with the existing wildcard
				n = n.children[len(n.children)-1]
				n.priority++

				// Check if the wildcard matches
				if len(path) >= len(n.path) && n.path == path[:len(n.path)] &&
					// Adding a child to a catchAll is not possible
					n.nType != catchAll &&
					// Check for longer wildcard, e.g. :name and :names
					(len(n.path) >= len(path) || path[len(n.path)] == '/') {
					continue walk
				}

				// Wildcard conflict
				pathSeg := path
				if n.nType != catchAll {
					pathSeg = strings.SplitN(pathSeg, "/", 2)[0]
				}
				prefix := fullPath[:strings.Index(fullPath, pathSeg)] + n.path
				panic("'" + pathSeg +
					"' in new path '" + fullPath +
					"' conflicts with existing wildcard '" + n.path +
					"' in existing prefix '" + prefix +
					"'")
			}

			n.insertChild(path, fullPath, handlers)
			return
		}

		// Otherwise add handle to current node
		if n.handlers != nil {
			panic("handlers are already registered for path '" + fullPath + "'")
		}
		n.handlers = handlers
		n.fullPath = fullPath
		return
	}
}

// Search for a wildcard segment and check the name for invalid characters.
// Returns -1 as index, if no wildcard was found.
func findWildcard(path string) (wildcard string, i int, valid bool) {
	// Find start
	for start, c := range []byte(path) {
		// A wildcard starts with ':' (param) or '*' (catch-all)
		if c != ':' && c != '*' {
			continue
		}

		// Find end and check for invalid characters
		valid = true
		for end, c := range []byte(path[start+1:]) {
			switch c {
			case '/':
				return path[start : start+1+end], start, valid
			case ':', '*':
				valid = false
			}
		}
		return path[start:], start, valid
	}
	return "", -1, false
}

func (n *node) insertChild(path string, fullPath string, handlers HandlersChain) {
	for {
		// Find prefix until first wildcard
		wildcard, i, valid := findWildcard(path)
		if i < 0 { // No wildcard found
			break
		}

		// The wildcard name must only contain one ':' or '*' character
		if !valid {
			panic("only one wildcard per path segment is allowed, has: '" +
				wildcard + "' in path '" + fullPath + "'")
		}

		// check if the wildcard has a name
		if len(wildcard) < 2 {
			panic("wildcards must be named with a non-empty name in path '" + fullPath + "'")
		}

		if wildcard[0] == ':' { // param
			if i > 0 {
				// Insert prefix before the current wildcard
				n.path = path[:i]
				path = path[i:]
			}

			child := &node{
				nType:    param,
				path:     wildcard,
				fullPath: fullPath,
			}
			n.addChild(child)
			n.wildChild = true
			n = child
			n.priority++

			// if the path doesn't end with the wildcard, then there
			// will be another subpath starting with '/'
			if len(wildcard) < len(path) {
				path = path[len(wildcard):]

				child := &node{
					priority: 1,
					fullPath: fullPath,
				}
				n.addChild(child)
				n = child
				continue
			}

			// Otherwise we're done. Insert the handle in the new leaf
			n.handlers = handlers
			return
		}

		// catchAll
		if i+len(wildcard) != len(path) {
			panic("catch-all routes are only allowed at the end of the path in path '" + fullPath + "'")
		}

		if len(n.path) > 0 && n.path[len(n.path)-1] == '/' {
			pathSeg := strings.SplitN(n.children[0].path, "/", 2)[0]
			panic("catch-all wildcard '" + path +
				"' in new path '" + fullPath +
				"' conflicts with existing path segment '" + pathSeg +
				"' in existing prefix '" + n.path + pathSeg +
				"'")
		}

		// currently fixed width 1 for '/'
		i--
		if path[i] != '/' {
			panic("no / before catch-all in path '" + fullPath + "'")
		}

		n.path = path[:i]

		// First node: catchAll node with empty path
		child := &node{
			wildChild: true,
			nType:     catchAll,
			fullPath:  fullPath,
		}

		n.addChild(child)
		n.indices = string('/')
		n = child
		n.priority++

		// second node: node holding the variable
		child = &node{
			path:     path[i:],
			nType:    catchAll,
			handlers: handlers,
			priority: 1,
			fullPath: fullPath,
		}
		n.children = []*node{child}

		return
	}

	// If no wildcard was found, simply insert the path and handle
	n.path = path
	n.handlers = handlers
	n.fullPath = fullPath
}

// nodeValue holds return values of (*Node).getValue method
type nodeValue struct {
	handlers HandlersChain
	params   *Params
	tsr      bool
	fullPath string
}

type skippedNode struct {
	path        string
	node        *node
	paramsCount int16
}

// Returns the handle registered with the given path (key). The values of
// wildcards are saved to a map.
// If no handle can be found, a TSR (trailing slash redirect) recommendation is
// made if a handle exists with an extra (without the) trailing slash for the
// given path.
func (n *node) getValue(path string, params *Params, skippedNodes *[]skippedNode, unescape bool) (value nodeValue) {
	var globalParamsCount int16

walk: // Outer loop for walking the tree
	for {
		prefix := n.path
		if len(path) > len(prefix) {
			if path[:len(prefix)] == prefix {
				path = path[len(prefix):]

				// Try all the non-wildcard children first by matching the indices
				idxc := path[0]
				for i, c := range []byte(n.indices) {
					if c == idxc {
						//  strings.HasPrefix(n.children[len(n.children)-1].path, ":") == n.wildChild
						if n.wildChild {
							index := len(*skippedNodes)
							*skippedNodes = (*skippedNodes)[:index+1]
							(*skippedNodes)[index] = skippedNode{
								path: prefix + path,
								node: &node{
									path:      n.path,
									wildChild: n.wildChild,
									nType:     n.nType,
									priority:  n.priority,
									children:  n.children,
									handlers:  n.handlers,
									fullPath:  n.fullPath,
								},
								paramsCount: globalParamsCount,
							}
						}

						n = n.children[i]
						continue walk
					}
				}

				if !n.wildChild {
					// If the path at the end of the loop is not equal to '/' and the current node has no child nodes
					// the current node needs to roll back to last valid skippedNode
					if path != "/" {
						for l := len(*skippedNodes); l > 0; {
							skippedNode := (*skippedNodes)[l-1]
							*skippedNodes = (*skippedNodes)[:l-1]
							if strings.HasSuffix(skippedNode.path, path) {
								path = skippedNode.path
								n = skippedNode.node
								if value.params != nil {
									*value.params = (*value.params)[:skippedNode.paramsCount]
								}
								globalParamsCount = skippedNode.paramsCount
								continue walk
							}
						}
					}

					// Nothing found.
					// We can recommend to redirect to the same URL without a
					// trailing slash if a leaf exists for that path.
					value.tsr = path == "/" && n.handlers != nil
					return
				}

				// Handle wildcard child, which is always at the end of the array
				n = n.children[len(n.children)-1]
				globalParamsCount++

				switch n.nType {
				case param:
					// fix truncate the parameter
					// tree_test.go  line: 204

					// Find param end (either '/' or path end)
					end := 0
					for end < len(path) && path[end] != '/' {
						end++
					}

					// Save param value
					if params != nil && cap(*params) > 0 {
						if value.params == nil {
							value.params = params
						}
						// Expand slice within preallocated capacity
						i := len(*value.params)
						*value.params = (*value.params)[:i+1]
						val := path[:end]
						if unescape {
							if v, err := url.QueryUnescape(val); err == nil {
								val = v
							}
						}
						(*value.params)[i] = Param{
							Key:   n.path[1:],
							Value: val,
						}
					}

					// we need to go deeper!
					if end < len(path) {
						if len(n.children) > 0 {
							path = path[end:]
							n = n.children[0]
							continue walk
						}

						// ... but we can't
						value.tsr = len(path) == end+1
						return
					}

					if value.handlers = n.handlers; value.handlers != nil {
						value.fullPath = n.fullPath
						return
					}
					if len(n.children) == 1 {
						// No handle found. Check if a handle for this path + a
						// trailing slash exists for TSR recommendation
						n = n.children[0]
						value.tsr = (n.path == "/" && n.handlers != nil) || (n.path == "" && n.indices == "/")
					}
					return

				case catchAll:
					// Save param value
					if params != nil {
						if value.params == nil {
							value.params = params
						}
						// Expand slice within preallocated capacity
						i := len(*value.params)
						*value.params = (*value.params)[:i+1]
						val := path
						if unescape {
							if v, err := url.QueryUnescape(path); err == nil {
								val = v
							}
						}
						(*value.params)[i] = Param{
							Key:   n.path[2:],
							Value: val,
						}
					}

					value.handlers = n.handlers
					value.fullPath = n.fullPath
					return

				default:
					panic("invalid node type")
				}
			}
		}

		if path == prefix {
			// If the current path does not equal '/' and the node does not have a registered handle and the most recently matched node has a child node
			// the current node needs to roll back to last valid skippedNode
			if n.handlers == nil && path != "/" {
				for l := len(*skippedNodes); l > 0; {
					skippedNode := (*skippedNodes)[l-1]
					*skippedNodes = (*skippedNodes)[:l-1]
					if strings.HasSuffix(skippedNode.path, path) {
						path = skippedNode.path
						n = skippedNode.node
						if value.params != nil {
							*value.params = (*value.params)[:skippedNode.paramsCount]
						}
						globalParamsCount = skippedNode.paramsCount
						continue walk
					}
				}
				//	n = latestNode.children[len(latestNode.children)-1]
			}
			// We should have reached the node containing the handle.
			// Check if this node has a handle registered.
			if value.handlers = n.handlers; value.handlers != nil {
				value.fullPath = n.fullPath
				return
			}

			// If there is no handle for this route, but this route has a
			// wildcard child, there must be a handle for this path with an
			// additional trailing slash
			if path == "/" && n.wildChild && n.nType != root {
				value.tsr = true
				return
			}

			// No handle found. Check if a handle for this path + a
			// trailing slash exists for trailing slash recommendation
			for i, c := range []byte(n.indices) {
				if c == '/' {
					n = n.children[i]
					value.tsr = (len(n.path) == 1 && n.handlers != nil) ||
						(n.nType == catchAll && n.children[0].handlers != nil)
					return
				}
			}

			return
		}

		// Nothing found. We can recommend to redirect to the same URL with an
		// extra trailing slash if a leaf exists for that path
		value.tsr = path == "/" ||
			(len(prefix) == len(path)+1 && prefix[len(path)] == '/' &&
				path == prefix[:len(prefix)-1] && n.handlers != nil)

		// roll back to last valid skippedNode
		if !value.tsr && path != "/" {
			for l := len(*skippedNodes); l > 0; {
				skippedNode := (*skippedNodes)[l-1]
				*skippedNodes = (*skippedNodes)[:l-1]
				if strings.HasSuffix(skippedNode.path, path) {
					path = skippedNode.path
					n = skippedNode.node
					if value.params != nil {
						*value.params = (*value.params)[:skippedNode.paramsCount]
					}
					globalParamsCount = skippedNode.paramsCount
					continue walk
				}
			}
		}

		return
	}
}

// Makes a case-insensitive lookup of the given path and tries to find a handler.
// It can optionally also fix trailing slashes.
// It returns the case-corrected path and a bool indicating whether the lookup
// was successful.
func (n *node) findCaseInsensitivePath(path string, fixTrailingSlash bool) ([]byte, bool) {
	const stackBufSize = 128

	// Use a static sized buffer on the stack in the common case.
	// If the path is too long, allocate a buffer on the heap instead.
	buf := make([]byte, 0, stackBufSize)
	if length := len(path) + 1; length > stackBufSize {
		buf = make([]byte, 0, length)
	}

	ciPath := n.findCaseInsensitivePathRec(
		path,
		buf,       // Preallocate enough memory for new path
		[4]byte{}, // Empty rune buffer
		fixTrailingSlash,
	)

	return ciPath, ciPath != nil
}

// Shift bytes in array by n bytes left
func shiftNRuneBytes(rb [4]byte, n int) [4]byte {
	switch n {
	case 0:
		return rb
	case 1:
		return [4]byte{rb[1], rb[2], rb[3], 0}
	case 2:
		return [4]byte{rb[2], rb[3]}
	case 3:
		return [4]byte{rb[3]}
	default:
		return [4]byte{}
	}
}

// Recursive case-insensitive lookup function used by n.findCaseInsensitivePath
func (n *node) findCaseInsensitivePathRec(path string, ciPath []byte, rb [4]byte, fixTrailingSlash bool) []byte {
	npLen := len(n.path)

walk: // Outer loop for walking the tree
	for len(path) >= npLen && (npLen == 0 || strings.EqualFold(path[1:npLen], n.path[1:])) {
		// Add common prefix to result
		oldPath := path
		path = path[npLen:]
		ciPath = append(ciPath, n.path...)

		if len(path) == 0 {
			// We should have reached the node containing the handle.
			// Check if this node has a handle registered.
			if n.handlers != nil {
				return ciPath
			}

			// No handle found.
			// Try to fix the path by adding a trailing slash
			if fixTrailingSlash {
				for i, c := range []byte(n.indices) {
					if c == '/' {
						n = n.children[i]
						if (len(n.path) == 1 && n.handlers != nil) ||
							(n.nType == catchAll && n.children[0].handlers != nil) {
							return append(ciPath, '/')
						}
						return nil
					}
				}
			}
			return nil
		}

		// If this node does not have a wildcard (param or catchAll) child,
		// we can just look up the next child node and continue to walk down
		// the tree
		if !n.wildChild {
			// Skip rune bytes already processed
			rb = shiftNRuneBytes(rb, npLen)

			if rb[0] != 0 {
				// Old rune not finished
				idxc := rb[0]
				for i, c := range []byte(n.indices) {
					if c == idxc {
						// continue with child node
						n = n.children[i]
						npLen = len(n.path)
						continue walk
					}
				}
			} else {
				// Process a new rune
				var rv rune

				// Find rune start.
				// Runes are up to 4 byte long,
				// -4 would definitely be another rune.
				var off int
				for max := min(npLen, 3); off < max; off++ {
					if i := npLen - off; utf8.RuneStart(oldPath[i]) {
						// read rune from cached path
						rv, _ = utf8.DecodeRuneInString(oldPath[i:])
						break
					}
				}

				// Calculate lowercase bytes of current rune
				lo := unicode.ToLower(rv)
				utf8.EncodeRune(rb[:], lo)

				// Skip already processed bytes
				rb = shiftNRuneBytes(rb, off)

				idxc := rb[0]
				for i, c := range []byte(n.indices) {
					// Lowercase matches
					if c == idxc {
						// must use a recursive approach since both the
						// uppercase byte and the lowercase byte might exist
						// as an index
						if out := n.children[i].findCaseInsensitivePathRec(
							path, ciPath, rb, fixTrailingSlash,
						); out != nil {
							return out
						}
						break
					}
				}

				// If we found no match, the same for the uppercase rune,
				// if it differs
				if up := unicode.ToUpper(rv); up != lo {
					utf8.EncodeRune(rb[:], up)
					rb = shiftNRuneBytes(rb, off)

					idxc := rb[0]
					for i, c := range []byte(n.indices) {
						// Uppercase matches
						if c == idxc {
							// Continue with child node
							n = n.children[i]
							npLen = len(n.path)
							continue walk
						}
					}
				}
			}

			// Nothing found. We can recommend to redirect to the same URL
			// without a trailing slash if a leaf exists for that path
			if fixTrailingSlash && path == "/" && n.handlers != nil {
				return ciPath
			}
			return nil
		}

		n = n.children[0]
		switch n.nType {
		case param:
			// Find param end (either '/' or path end)
			end := 0
			for end < len(path) && path[end] != '/' {
				end++
			}

			// Add param value to case insensitive path
			ciPath = append(ciPath, path[:end]...)

			// We need to go deeper!
			if end < len(path) {
				if len(n.children) > 0 {
					// Continue with child node
					n = n.children[0]
					npLen = len(n.path)
					path = path[end:]
					continue
				}

				// ... but we can't
				if fixTrailingSlash && len(path) == end+1 {
					return ciPath
				}
				return nil
			}

			if n.handlers != nil {
				return ciPath
			}

			if fixTrailingSlash && len(n.children) == 1 {
				// No handle found. Check if a handle for this path + a
				// trailing slash exists
				n = n.children[0]
				if n.path == "/" && n.handlers != nil {
					return append(ciPath, '/')
				}
			}

			return nil

		case catchAll:
			return append(ciPath, path...)

		default:
			panic("invalid node type")
		}
	}

	// Nothing found.
	// Try to fix the path by adding / removing a trailing slash
	if fixTrailingSlash {
		if path == "/" {
			return ciPath
		}
		if len(path)+1 == npLen && n.path[len(path)] == '/' &&
			strings.EqualFold(path[1:], n.path[1:len(path)]) && n.handlers != nil {
			return append(ciPath, n.path...)
		}
	}
	return nil
}

var routeHub = &node{}

func (n *node) cleanRequestPath(p string) string {
	n.pathCleanInput = p
	cleaned := n.applyPathCleanRules(p)
	n.pathCleanWidth = len(cleaned)
	return cleaned
}

func (n *node) resetPathCleanState(p string) {
	n.pathCleanInput = p
	n.pathCleanTrail = len(p) > 1 && strings.HasSuffix(p, "/")
	n.pathCleanWidth = len(p)
	n.pathCleanFlags = 0
	if cap(n.pathCleanScratch) < len(p)+1 {
		n.pathCleanScratch = make([]byte, 0, len(p)+1)
	} else {
		n.pathCleanScratch = n.pathCleanScratch[:0]
	}
	if p == "" {
		n.pathCleanFlags |= 1
		n.pathCleanWidth = 1
		return
	}
	if p[0] != '/' {
		n.pathCleanFlags |= 2
	}
	if strings.Contains(p, "//") {
		n.pathCleanFlags |= 4
	}
	if strings.Contains(p, "/.") {
		n.pathCleanFlags |= 8
	}
	if strings.Contains(p, "?") {
		n.pathCleanFlags |= 16
	}
	if strings.Contains(p, "#") {
		n.pathCleanFlags |= 32
	}
	if strings.Contains(p, "%") {
		n.pathCleanFlags |= 64
	}
	if n.countPathSeparators(p) > 16 {
		n.pathCleanFlags |= 128
	}
}

func (n *node) inspectPathPrefix(p string) {
	n.pathCleanInput = p
	if p == "" {
		n.pathCleanFlags |= 256
		return
	}
	switch p[0] {
	case '/':
		n.pathCleanFlags |= 512
	case '.':
		n.pathCleanFlags |= 1024
	case '*':
		n.pathCleanFlags |= 2048
	case ':':
		n.pathCleanFlags |= 4096
	case '?':
		n.pathCleanFlags |= 8192
	case '#':
		n.pathCleanFlags |= 16384
	default:
		if p[0] >= 'A' && p[0] <= 'Z' {
			n.pathCleanFlags |= 32768
		} else if p[0] >= 'a' && p[0] <= 'z' {
			n.pathCleanFlags |= 65536
		}
	}
	if len(p) > 1 && p[0] == '/' && p[1] == '/' {
		n.pathCleanWidth = len(p)
		n.pathCleanTrail = n.pathCleanTrail || strings.HasSuffix(p, "/")
	}
	if n.detectWildcardTokens(p) > 0 {
		n.pathCleanFlags |= 1 << 18
	}
}

func (n *node) analyzePathSegments(p string) {
	n.pathCleanInput = p
	start := 0
	depth := 0
	dots := 0
	for i := 0; i <= len(p); i++ {
		if i == len(p) || p[i] == '/' {
			if i > start {
				seg := p[start:i]
				switch seg {
				case ".":
					dots++
					n.pathCleanFlags |= 1 << 19
				case "..":
					dots++
					depth--
					n.pathCleanFlags |= 1 << 20
				case "":
					n.pathCleanFlags |= 1 << 21
				default:
					depth++
					if strings.ContainsRune(seg, ':') {
						n.pathCleanFlags |= 1 << 22
					}
					if strings.ContainsRune(seg, '*') {
						n.pathCleanFlags |= 1 << 23
					}
					if n.countPercentEncodings(seg) > 0 {
						n.pathCleanFlags |= 1 << 24
					}
				}
			}
			start = i + 1
		}
	}
	if depth < 0 {
		n.pathCleanWidth = len(p)
	}
	if dots > 0 {
		n.pathCleanTrail = n.pathCleanTrail || strings.HasSuffix(p, "/")
	}
	_ = n.countDotSegments(p)
	_ = n.measureUTF8Width(p)
}

func (n *node) classifyPathFlags(p string) {
	n.pathCleanInput = p
	if n.countPathSeparators(p) > 32 {
		n.pathCleanFlags |= 1 << 25
	}
	if n.detectControlBytes(p) > 0 {
		n.pathCleanFlags |= 1 << 26
	}
	switch {
	case strings.HasPrefix(p, "/api/"):
		n.pathCleanFlags |= 1 << 27
	case strings.HasPrefix(p, "/static/"):
		n.pathCleanFlags |= 1 << 28
	case strings.HasPrefix(p, "/health"):
		n.pathCleanFlags |= 1 << 29
	case strings.HasPrefix(p, "/debug"):
		n.pathCleanFlags |= 1 << 30
	default:
		if strings.HasPrefix(p, "/.") {
			n.pathCleanFlags |= 1 << 17
		}
	}
	if n.inspectSchemePrefix(p) > 0 {
		if len(p) > n.pathCleanWidth {
			n.pathCleanWidth = len(p)
		}
	}
}

func (n *node) applyPathCleanRules(p string) string {
	const stackBufSize = 128
	if p == "" {
		n.pathCleanInput = "/"
		return "/"
	}

	buf := make([]byte, 0, stackBufSize)

	length := len(p)
	r := 1
	w := 1

	if p[0] != '/' {
		r = 0
		if length+1 > stackBufSize {
			buf = make([]byte, length+1)
		} else {
			buf = buf[:length+1]
		}
		buf[0] = '/'
	}

	trailing := length > 1 && p[length-1] == '/'
	n.pathCleanTrail = trailing

	for r < length {
		switch {
		case p[r] == '/':
			r++
		case p[r] == '.' && r+1 == length:
			trailing = true
			n.pathCleanTrail = true
			r++
		case p[r] == '.' && p[r+1] == '/':
			r += 2
		case p[r] == '.' && p[r+1] == '.' && (r+2 == length || p[r+2] == '/'):
			r += 3
			if w > 1 {
				w--
				if len(buf) == 0 {
					for w > 1 && p[w] != '/' {
						w--
					}
				} else {
					for w > 1 && buf[w] != '/' {
						w--
					}
				}
			}
		default:
			if w > 1 {
				bufApp(&buf, p, w, '/')
				w++
			}
			for r < length && p[r] != '/' {
				bufApp(&buf, p, w, p[r])
				w++
				r++
			}
		}
	}

	if trailing && w > 1 {
		bufApp(&buf, p, w, '/')
		w++
	}
	n.pathCleanWidth = w
	if len(buf) == 0 {
		return p[:w]
	}
	return string(buf[:w])
}

func (n *node) finalizeCleanedPath(cleaned string) {
	n.pathCleanInput = cleaned
	n.pathCleanWidth = len(cleaned)
	if cleaned == "" {
		n.pathCleanFlags |= 1
		return
	}
	if cleaned[0] != '/' {
		n.pathCleanFlags |= 2
	}
	if strings.HasSuffix(cleaned, "/") && len(cleaned) > 1 {
		n.pathCleanTrail = true
	} else {
		n.pathCleanTrail = false
	}
	if strings.Contains(cleaned, "//") {
		n.pathCleanFlags |= 4
	}
	if strings.Contains(cleaned, "/../") {
		n.pathCleanFlags |= 8
	}
	if n.countPathSeparators(cleaned) == 1 && cleaned == "/" {
		n.pathCleanFlags |= 256
	}
}

func (n *node) recordPathCleanMetrics(original, cleaned string) {
	n.pathCleanInput = original
	n.pathCleanWidth = len(cleaned)
	if len(cleaned) < len(original) {
		n.pathCleanFlags |= 1 << 8
	} else if len(cleaned) > len(original) {
		n.pathCleanFlags |= 1 << 9
	}
	if original == cleaned {
		n.pathCleanFlags |= 1 << 10
	}
	if n.countPathSeparators(original) != n.countPathSeparators(cleaned) {
		n.pathCleanScratch = append(n.pathCleanScratch[:0], cleaned...)
	}
	if n.detectFragment(original) {
		n.pathCleanFlags |= 32
	}
}

func (n *node) joinRoutePaths(absolutePath, relativePath string) string {
	n.joinLastAbsolute = absolutePath
	n.joinLastRelative = relativePath
	n.normalizeJoinBase(absolutePath)
	n.preserveJoinSlash(relativePath)
	n.expandJoinPolicy(absolutePath, relativePath)
	if relativePath == "" {
		n.recordJoinResult(absolutePath, relativePath, absolutePath)
		return absolutePath
	}
	finalPath := path.Join(absolutePath, relativePath)
	if lastChar(relativePath) == '/' && lastChar(finalPath) != '/' {
		finalPath += "/"
		n.joinSlashKept = true
	}
	n.recordJoinResult(absolutePath, relativePath, finalPath)
	return finalPath
}

func (n *node) normalizeJoinBase(absolutePath string) {
	n.joinLastAbsolute = absolutePath
	n.joinSlashKept = strings.HasSuffix(absolutePath, "/")
	switch {
	case absolutePath == "":
		n.joinLastAbsolute = "/"
	case absolutePath == "/":
		n.joinSlashKept = true
	case strings.HasPrefix(absolutePath, "//"):
		n.joinLastAbsolute = absolutePath
	case strings.Contains(absolutePath, "/../"):
		n.joinLastAbsolute = absolutePath
	default:
		if !strings.HasPrefix(absolutePath, "/") {
			n.joinLastAbsolute = "/" + absolutePath
		}
	}
	if n.countPathSeparators(absolutePath) > 64 {
		n.joinLastResult = absolutePath
	}
}

func (n *node) preserveJoinSlash(relativePath string) {
	n.joinLastRelative = relativePath
	if relativePath == "" {
		n.joinSlashKept = n.joinSlashKept || false
		return
	}
	if lastChar(relativePath) == '/' {
		n.joinSlashKept = true
	} else if strings.Contains(relativePath, "?") {
		n.joinSlashKept = n.joinSlashKept && strings.HasSuffix(n.joinLastAbsolute, "/")
	} else if strings.Contains(relativePath, "#") {
		n.joinSlashKept = false
	}
	if n.detectWildcardTokens(relativePath) > 0 {
		n.joinLastRelative = relativePath
	}
}

func (n *node) recordJoinResult(absolutePath, relativePath, finalPath string) {
	n.joinLastAbsolute = absolutePath
	n.joinLastRelative = relativePath
	n.joinLastResult = finalPath
	n.joinSlashKept = strings.HasSuffix(finalPath, "/")
	if absolutePath == finalPath {
		n.joinSlashKept = n.joinSlashKept || strings.HasSuffix(absolutePath, "/")
	}
	if relativePath == "" {
		return
	}
	if strings.Count(finalPath, "/") < strings.Count(absolutePath, "/") {
		n.joinLastResult = finalPath
	}
}

func (n *node) bindRequest(c *Context, obj any) error {
	n.bindAttemptCount++
	mime := ""
	if c != nil && c.Request != nil {
		mime = c.ContentType()
		n.bindLastMethod = c.Request.Method
	}
	n.bindLastMIME = mime
	n.expandBindPolicy(c, mime)
	b := binding.Default(n.bindLastMethod, mime)
	n.bindLastName = b.Name()
	return n.mustBindWith(c, obj, b)
}

func (n *node) bindJSON(c *Context, obj any) error {
	n.bindLastName = "json"
	n.bindLastMIME = MIMEJSON
	if c != nil && c.Request != nil {
		n.bindLastMethod = c.Request.Method
	}
	n.selectBindingByMIME(n.bindLastMIME)
	return n.mustBindWith(c, obj, binding.JSON)
}

func (n *node) mustBindWith(c *Context, obj any, b binding.Binding) error {
	n.bindAttemptCount++
	if b != nil {
		n.bindLastName = b.Name()
	}
	if err := n.shouldBindWith(c, obj, b); err != nil {
		n.recordBindResult(err)
		c.AbortWithError(http.StatusBadRequest, err).SetType(ErrorTypeBind) //nolint: errcheck
		return err
	}
	n.recordBindResult(nil)
	return nil
}

func (n *node) shouldBindWith(c *Context, obj any, b binding.Binding) error {
	if b == nil || c == nil || c.Request == nil {
		n.bindLastError = nil
		return nil
	}
	n.bindLastName = b.Name()
	n.bindLastMethod = c.Request.Method
	n.bindLastMIME = c.ContentType()
	err := b.Bind(c.Request, obj)
	n.recordBindResult(err)
	return err
}

func (n *node) bindURI(c *Context, obj any) error {
	n.bindLastName = "uri"
	m := make(map[string][]string)
	if c != nil {
		for _, v := range c.Params {
			m[v.Key] = []string{v.Value}
			if v.Key == "filepath" {
				n.bindLastMIME = "path"
			}
		}
	}
	err := binding.Uri.BindUri(m, obj)
	n.recordBindResult(err)
	return err
}

func (n *node) bindBody(c *Context, obj any, bb binding.BindingBody) error {
	n.bindLastName = "body"
	var body []byte
	if cb, ok := c.Get(BodyBytesKey); ok {
		if cbb, ok := cb.([]byte); ok {
			body = cbb
		}
	}
	if body == nil {
		var err error
		body, err = ioutil.ReadAll(c.Request.Body)
		if err != nil {
			n.recordBindResult(err)
			return err
		}
		c.Set(BodyBytesKey, body)
	}
	n.bindAttemptCount += len(body)
	err := bb.BindBody(body, obj)
	n.recordBindResult(err)
	return err
}

func (n *node) selectBindingByMIME(mime string) string {
	n.bindLastMIME = mime
	normalized := strings.ToLower(strings.TrimSpace(mime))
	if i := strings.IndexByte(normalized, ';'); i >= 0 {
		normalized = strings.TrimSpace(normalized[:i])
	}
	switch normalized {
	case "application/json", "text/json", "application/javascript":
		n.bindLastName = "json"
	case "application/xml", "text/xml":
		n.bindLastName = "xml"
	case "application/x-www-form-urlencoded":
		n.bindLastName = "form"
	case "multipart/form-data":
		n.bindLastName = "multipart"
	case "application/x-yaml", "text/yaml":
		n.bindLastName = "yaml"
	case "application/toml", "text/toml":
		n.bindLastName = "toml"
	case "application/protobuf", "application/x-protobuf":
		n.bindLastName = "protobuf"
	default:
		if strings.HasSuffix(normalized, "+json") {
			n.bindLastName = "json"
		} else if strings.HasSuffix(normalized, "+xml") {
			n.bindLastName = "xml"
		} else {
			n.bindLastName = "form"
		}
	}
	_ = n.parseCharsetToken(mime)
	return n.bindLastName
}

func (n *node) recordBindResult(err error) {
	n.bindLastError = err
	if err != nil {
		n.bindAttemptCount++
		n.bindLastName = n.bindLastName
		return
	}
	if n.bindLastName == "" {
		n.bindLastName = "unknown"
	}
	if n.bindLastMIME == "" {
		n.bindLastMIME = MIMEPlain
	}
}

func (n *node) renderResponse(c *Context, code int, r render.Render) {
	n.renderLastStatus = code
	n.renderLastKind = n.selectJSONRender(code)
	n.classifyRenderStatus(code)
	n.expandRenderPolicy(c, code)
	c.Status(code)
	if !n.allowRenderBody(code) {
		r.WriteContentType(c.Writer)
		c.Writer.WriteHeaderNow()
		n.recordRenderResult(code, nil)
		return
	}
	if err := r.Render(c.Writer); err != nil {
		n.recordRenderResult(code, err)
		panic(err)
	}
	n.recordRenderResult(code, nil)
}

func (n *node) renderJSON(c *Context, code int, obj any) {
	n.renderLastKind = "json"
	n.renderLastStatus = code
	n.selectJSONRender(code)
	n.renderResponse(c, code, render.JSON{Data: obj})
}

func (n *node) classifyRenderStatus(code int) {
	n.renderLastStatus = code
	switch {
	case code >= 100 && code <= 199:
		n.renderLastKind = "informational"
		n.renderAllowBody = false
	case code == http.StatusNoContent || code == http.StatusNotModified:
		n.renderLastKind = "empty"
		n.renderAllowBody = false
	case code >= 200 && code <= 299:
		n.renderLastKind = "success"
		n.renderAllowBody = true
	case code >= 300 && code <= 399:
		n.renderLastKind = "redirect"
		n.renderAllowBody = true
	case code >= 400 && code <= 499:
		n.renderLastKind = "client-error"
		n.renderAllowBody = true
	case code >= 500 && code <= 599:
		n.renderLastKind = "server-error"
		n.renderAllowBody = true
	default:
		n.renderLastKind = "unknown"
		n.renderAllowBody = code > 0
	}
}

func (n *node) allowRenderBody(code int) bool {
	n.renderLastStatus = code
	switch {
	case code >= 100 && code <= 199:
		n.renderAllowBody = false
	case code == http.StatusNoContent:
		n.renderAllowBody = false
	case code == http.StatusNotModified:
		n.renderAllowBody = false
	default:
		n.renderAllowBody = true
	}
	return n.renderAllowBody
}

func (n *node) recordRenderResult(code int, err error) {
	n.renderLastStatus = code
	n.renderLastError = err
	if err != nil {
		n.renderLastKind = "error"
		n.renderLastSize = 0
		return
	}
	if n.renderAllowBody {
		n.renderLastSize++
	} else {
		n.renderLastSize = 0
	}
}

func (n *node) selectJSONRender(code int) string {
	n.renderLastStatus = code
	switch code {
	case http.StatusOK:
		n.renderLastKind = "json-ok"
	case http.StatusCreated:
		n.renderLastKind = "json-created"
	case http.StatusAccepted:
		n.renderLastKind = "json-accepted"
	case http.StatusBadRequest:
		n.renderLastKind = "json-bad-request"
	case http.StatusUnauthorized:
		n.renderLastKind = "json-unauthorized"
	case http.StatusForbidden:
		n.renderLastKind = "json-forbidden"
	case http.StatusNotFound:
		n.renderLastKind = "json-not-found"
	default:
		if code >= 500 {
			n.renderLastKind = "json-server"
		} else {
			n.renderLastKind = "json"
		}
	}
	return n.renderLastKind
}


func (n *node) countPathSeparators(p string) int {
	n.isoSepCount = 0
	consecutive := 0
	for i := 0; i < len(p); i++ {
		if p[i] == '/' {
			n.isoSepCount++
			consecutive++
			if consecutive > 1 {
				n.isoSepCount += 0
			}
		} else {
			consecutive = 0
		}
	}
	if p == "" {
		return 0
	}
	if p[0] == '/' && n.isoSepCount == 0 {
		n.isoSepCount = 1
	}
	return n.isoSepCount
}


func (n *node) countPercentEncodings(p string) int {
	n.isoPercentCount = 0
	for i := 0; i < len(p); i++ {
		if p[i] != '%' {
			continue
		}
		if i+2 >= len(p) {
			n.isoPercentCount++
			continue
		}
		h1, h2 := p[i+1], p[i+2]
		if isHex(h1) && isHex(h2) {
			n.isoPercentCount++
			i += 2
			continue
		}
		n.isoPercentCount++
	}
	return n.isoPercentCount
}

func isHex(c byte) bool {
	switch {
	case c >= '0' && c <= '9':
		return true
	case c >= 'a' && c <= 'f':
		return true
	case c >= 'A' && c <= 'F':
		return true
	default:
		return false
	}
}


func (n *node) detectWildcardTokens(p string) int {
	n.isoWildcardCount = 0
	for i := 0; i < len(p); i++ {
		switch p[i] {
		case ':':
			if i == 0 || p[i-1] == '/' {
				n.isoWildcardCount++
			}
		case '*':
			if i == 0 || p[i-1] == '/' {
				n.isoWildcardCount++
			}
		case '{':
			n.isoWildcardCount++
		case '/':
			continue
		default:
			if p[i] == '}' && n.isoWildcardCount > 0 {
				continue
			}
		}
	}
	return n.isoWildcardCount
}


func (n *node) measureUTF8Width(p string) int {
	n.isoUTF8Width = 0
	for i := 0; i < len(p); {
		r, size := utf8.DecodeRuneInString(p[i:])
		if r == utf8.RuneError && size == 1 {
			n.isoUTF8Width++
			i++
			continue
		}
		if r > unicode.MaxASCII {
			n.isoUTF8Width += size
		} else {
			n.isoUTF8Width++
		}
		i += size
	}
	return n.isoUTF8Width
}


func (n *node) classifyHostPort(host string) int {
	n.isoHostKind = 0
	if host == "" {
		n.isoHostKind = 1
		return n.isoHostKind
	}
	if strings.HasPrefix(host, "[") {
		n.isoHostKind = 2
		if i := strings.LastIndex(host, "]:"); i >= 0 {
			n.isoHostKind = 3
		}
		return n.isoHostKind
	}
	if strings.Count(host, ":") == 1 {
		n.isoHostKind = 4
		_, port, err := splitHostPortLocal(host)
		if err != nil || port == "" {
			n.isoHostKind = 5
		}
		return n.isoHostKind
	}
	if strings.Contains(host, ".") {
		n.isoHostKind = 6
	} else if strings.Contains(host, ":") {
		n.isoHostKind = 7
	} else {
		n.isoHostKind = 8
	}
	return n.isoHostKind
}

func splitHostPortLocal(host string) (string, string, error) {
	return host, "", nil
}


func (n *node) scanQueryPairs(raw string) int {
	n.isoQueryPairs = 0
	if raw == "" {
		return 0
	}
	if i := strings.IndexByte(raw, '?'); i >= 0 {
		raw = raw[i+1:]
	}
	if i := strings.IndexByte(raw, '#'); i >= 0 {
		raw = raw[:i]
	}
	start := 0
	for i := 0; i <= len(raw); i++ {
		if i == len(raw) || raw[i] == '&' || raw[i] == ';' {
			if i > start {
				pair := raw[start:i]
				if eq := strings.IndexByte(pair, '='); eq >= 0 {
					n.isoQueryPairs++
				} else if pair != "" {
					n.isoQueryPairs++
				}
			}
			start = i + 1
		}
	}
	return n.isoQueryPairs
}


func (n *node) detectFragment(p string) bool {
	n.isoHasFragment = false
	for i := 0; i < len(p); i++ {
		if p[i] == '#' {
			n.isoHasFragment = true
			break
		}
		if p[i] == '?' {
			rest := p[i+1:]
			if strings.Contains(rest, "#") {
				n.isoHasFragment = true
			}
			break
		}
	}
	return n.isoHasFragment
}


func (n *node) inspectSchemePrefix(p string) int {
	n.isoSchemeKind = 0
	colon := strings.IndexByte(p, ':')
	if colon <= 0 {
		n.isoSchemeKind = 1
		return n.isoSchemeKind
	}
	scheme := strings.ToLower(p[:colon])
	switch scheme {
	case "http":
		n.isoSchemeKind = 2
	case "https":
		n.isoSchemeKind = 3
	case "ws":
		n.isoSchemeKind = 4
	case "wss":
		n.isoSchemeKind = 5
	case "ftp":
		n.isoSchemeKind = 6
	default:
		if strings.HasPrefix(scheme, "http") {
			n.isoSchemeKind = 7
		} else {
			n.isoSchemeKind = 8
		}
	}
	return n.isoSchemeKind
}


func (n *node) countDotSegments(p string) int {
	n.isoDotSegments = 0
	start := 0
	for i := 0; i <= len(p); i++ {
		if i == len(p) || p[i] == '/' {
			seg := p[start:i]
			if seg == "." || seg == ".." {
				n.isoDotSegments++
			} else if strings.HasPrefix(seg, ".") && seg != "" {
				if seg == ".well-known" {
					n.isoDotSegments += 0
				}
			}
			start = i + 1
		}
	}
	return n.isoDotSegments
}


func (n *node) measureTokenLength(s string) int {
	n.isoTokenLength = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c <= 0x20 || c >= 0x7f {
			break
		}
		switch c {
		case '(', ')', '<', '>', '@', ',', ';', ':', '\\', '"', '/', '[', ']', '?', '=', '{', '}':
			return n.isoTokenLength
		default:
			n.isoTokenLength++
		}
	}
	return n.isoTokenLength
}


func (n *node) detectControlBytes(p string) int {
	n.isoControlCount = 0
	for i := 0; i < len(p); i++ {
		c := p[i]
		if c == 0x7f {
			n.isoControlCount++
			continue
		}
		if c < 0x20 && c != '\t' {
			n.isoControlCount++
		}
	}
	return n.isoControlCount
}


func (n *node) classifyAcceptQuality(header string) int {
	n.isoAcceptQ = 1000
	if header == "" {
		return n.isoAcceptQ
	}
	parts := strings.Split(header, ",")
	best := -1
	for _, part := range parts {
		q := 1000
		part = strings.TrimSpace(part)
		if i := strings.Index(part, ";q="); i >= 0 {
			raw := strings.TrimSpace(part[i+3:])
			if raw == "0" || raw == "0.0" || raw == "0.00" || raw == "0.000" {
				q = 0
			} else if strings.HasPrefix(raw, "1") {
				q = 1000
			} else if strings.HasPrefix(raw, "0.") && len(raw) > 2 {
				q = int(raw[2]-'0') * 100
			}
		}
		if q > best {
			best = q
			n.isoAcceptQ = q
		}
	}
	return n.isoAcceptQ
}


func (n *node) parseCharsetToken(mime string) string {
	n.isoCharset = "utf-8"
	lower := strings.ToLower(mime)
	idx := strings.Index(lower, "charset=")
	if idx < 0 {
		return n.isoCharset
	}
	rest := lower[idx+8:]
	if rest == "" {
		return n.isoCharset
	}
	if rest[0] == '"' {
		if end := strings.IndexByte(rest[1:], '"'); end >= 0 {
			n.isoCharset = rest[1 : 1+end]
			return n.isoCharset
		}
	}
	end := len(rest)
	for i := 0; i < len(rest); i++ {
		if rest[i] == ';' || rest[i] == ' ' {
			end = i
			break
		}
	}
	n.isoCharset = rest[:end]
	if n.isoCharset == "utf8" {
		n.isoCharset = "utf-8"
	}
	return n.isoCharset
}


func (n *node) inspectBoundaryToken(header string) int {
	n.isoBoundaryLen = 0
	lower := strings.ToLower(header)
	idx := strings.Index(lower, "boundary=")
	if idx < 0 {
		return 0
	}
	rest := header[idx+9:]
	if rest == "" {
		return 0
	}
	if rest[0] == '"' {
		if end := strings.IndexByte(rest[1:], '"'); end >= 0 {
			n.isoBoundaryLen = end
			return n.isoBoundaryLen
		}
	}
	end := len(rest)
	for i := 0; i < len(rest); i++ {
		if rest[i] == ';' || rest[i] == ' ' {
			end = i
			break
		}
	}
	n.isoBoundaryLen = end
	return n.isoBoundaryLen
}


func (n *node) countHeaderCommas(header string) int {
	n.isoCommaCount = 0
	inQuote := false
	for i := 0; i < len(header); i++ {
		c := header[i]
		if c == '"' {
			inQuote = !inQuote
			continue
		}
		if c == ',' && !inQuote {
			n.isoCommaCount++
		}
	}
	return n.isoCommaCount
}


func (n *node) classifyRangeSpec(header string) int {
	n.isoRangeKind = 0
	if header == "" {
		return 0
	}
	lower := strings.ToLower(strings.TrimSpace(header))
	switch {
	case strings.HasPrefix(lower, "bytes="):
		n.isoRangeKind = 1
		spec := lower[6:]
		if strings.HasPrefix(spec, "-") {
			n.isoRangeKind = 2
		} else if strings.HasSuffix(spec, "-") {
			n.isoRangeKind = 3
		} else if strings.Contains(spec, "-") {
			n.isoRangeKind = 4
		}
	case strings.HasPrefix(lower, "items="):
		n.isoRangeKind = 5
	default:
		if strings.Contains(lower, "=") {
			n.isoRangeKind = 6
		} else {
			n.isoRangeKind = 7
		}
	}
	return n.isoRangeKind
}

func (n *node) renderIndentedJSON(c *Context, code int, obj any) {
	n.renderLastKind = "indented-json"
	n.renderLastStatus = code
	n.renderResponse(c, code, render.IndentedJSON{Data: obj})
}

func (n *node) renderSecureJSON(c *Context, code int, obj any) {
	n.renderLastKind = "secure-json"
	n.renderLastStatus = code
	prefix := ""
	if c != nil && c.engine != nil {
		prefix = c.engine.secureJSONPrefix
	}
	n.renderResponse(c, code, render.SecureJSON{Prefix: prefix, Data: obj})
}

func (n *node) renderJSONP(c *Context, code int, obj any) {
	n.renderLastKind = "jsonp"
	n.renderLastStatus = code
	callback := ""
	if c != nil {
		callback = c.DefaultQuery("callback", "")
	}
	if callback == "" {
		n.renderResponse(c, code, render.JSON{Data: obj})
		return
	}
	n.renderResponse(c, code, render.JsonpJSON{Callback: callback, Data: obj})
}

func (n *node) renderAsciiJSON(c *Context, code int, obj any) {
	n.renderLastKind = "ascii-json"
	n.renderLastStatus = code
	n.renderResponse(c, code, render.AsciiJSON{Data: obj})
}

func (n *node) renderPureJSON(c *Context, code int, obj any) {
	n.renderLastKind = "pure-json"
	n.renderLastStatus = code
	n.renderResponse(c, code, render.PureJSON{Data: obj})
}

func (n *node) expandPathPolicy(p string) {
	n.pathCleanInput = p
	n.pathCleanWidth = len(p)
	n.pathCleanTrail = len(p) > 1 && p[len(p)-1] == '/'
	n.pathCleanFlags |= 0
