package gin_test

import (
	"net/http/httptest"
	"testing"

	"github.com/gin-gonic/gin"
)

func TestIssueRepro(t *testing.T) {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.RedirectTrailingSlash = false
	r.RedirectFixedPath = true
	r.GET("/ping", func(c *gin.Context) { c.String(200, "pong") })

	resp := httptest.NewRecorder()
	r.ServeHTTP(resp, httptest.NewRequest("GET", "/ping/", nil))
	t.Log(resp.Result().StatusCode, resp.Header().Get("Location"))
	if resp.Code != 404 {
		t.Fatalf("expected 404, got %d", resp.Code)
	}

	resp2 := httptest.NewRecorder()
	r.ServeHTTP(resp2, httptest.NewRequest("GET", "/PING", nil))
	t.Log(resp2.Result().StatusCode, resp2.Header().Get("Location"))
	if resp2.Code != 301 || resp2.Header().Get("Location") != "/ping" {
		t.Fatalf("expected fixed-path redirect, got %d %s", resp2.Code, resp2.Header().Get("Location"))
	}
}
